        /**
         * @struct someiphdr
         * Represents a SOME/IP protocol header
         */
#pragma pack(push, 1)
        struct someiphdr
        {
                /** Service ID */
                uint16_t serviceID;
                /** Method ID. Most significant bit 0 when E2E communication. 1 when SOME/IP event */
                uint16_t methodID;
                /** Length. Also covers payload. Excludes serviceID, methodID and length field itself */
                uint32_t length;
                /** Client ID */
                uint16_t clientID;
                /** Session ID */
                uint16_t sessionID;
                /** Protocol Version */
                uint8_t protocolVersion;
                /** Interface Version */
                uint8_t interfaceVersion;
                /** Message Type */
                uint8_t msgType;
                /** Return Code */
                uint8_t returnCode;
        };
#pragma pack(pop)

